mapper.select:
SELECT A.*,B.* FROM( SELECT tt1.rnum no, tt1.report_id, tt1.report_member_id, tt1.comment_id, tt1.reason, tt1.detail, tt1.status, tt1.processed_by_member_id, tt1.process_note, TO_CHAR(tt1.created_dt,'YYYY/MM/DD HH24:MI:SS') created_dt, TO_CHAR(tt1.processed_dt,'YYYY/MM/DD HH24:MI:SS') processed_dt FROM( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM report_comment
ORDER BY created_dt DESC, report_id DESC )t1 WHERE ROWNUM <= ( #{pageSize} * (#{pageNo} -1 ) + #{pageSize} ) )tt1 WHERE rnum >= ( #{pageSize} * (#{pageNo} -1 ) + 1 ) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM report_comment
) B
